import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int)(n % k));
            n /= k;
        }

        int size = k + 1;
        long MOD = 1000000007;

        long[][] matrix = new long[size][size];
        for (int j = 0; j <= k; ++j) {
            matrix[0][j] = 1;
            matrix[j][j] = 1;
        }

        // Function to multiply matrices
        java.util.function.BiFunction<long[][], long[][], long[][]> multiplyMatrices = (A, B) -> {
            long[][] result = new long[size][size];
            for (int i = 0; i <= k; ++i) {
                for (int j = 0; j <= k; ++j) {
                    long sum = 0;
                    for (int l = 0; l <= k; ++l) {
                        sum += A[i][l] * B[l][j];
                    }
                    result[i][j] = sum % MOD;
                }
            }
            return result;
        };

        // Function to perform matrix exponentiation
        java.util.function.BiFunction<long[][], Long, long[][]> matrixPower = (base, exp) -> {
            long[][] res = new long[size][size];
            for (int i = 0; i <= k; ++i) {
                res[i][i] = 1;
            }
            long e = exp;
            long[][] b = base;
            while (e > 0) {
                if ((e & 1) == 1) {
                    res = multiplyMatrices.apply(res, b);
                }
                b = multiplyMatrices.apply(b, b);
                e >>= 1;
            }
            return res;
        };

        long[][] A = new long[size][size];
        for (int i = 0; i <= k; ++i) {
            System.arraycopy(matrix[i], 0, A[i], 0, size);
        }

        long totalSumMod = 0;
        for (int i = digits.size() - 1; i >= 0; --i) {
            int digit = digits.get(i);
            for (int j = 0; j < digit; ++j) {
                long[][] temp = matrixPower.apply(A, (long)((j + totalSumMod) % k));
                for (int x = 0; x <= k; ++x) {
                    for (int y = 0; y <= k; ++y) {
                        matrix[x][y] = (matrix[x][y] + temp[x][y]) % MOD;
                    }
                }
            }
            totalSumMod = (totalSumMod + digit) % k;
        }

        long finalResult = 0;
        for (int i = 0; i <= k; ++i) {
            finalResult = (finalResult + matrix[i][k]) % MOD;
        }

        System.out.println(finalResult);
        sc.close();
    }
}
